<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();$d=db();
$q=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';$genre=is_string($_GET['genre']??null)&&ctype_digit($_GET['genre'])?(int)$_GET['genre']:0;$mine=($_GET['mine']??'')==='1';$like='%'.$q.'%';
$sql='SELECT s.*,m.name AS genre,u.username FROM z6_song s JOIN z6_musictype m ON m.idmt=s.idmt JOIN z6_users u ON u.id=s.idu WHERE '.music_access_sql().' AND (s.title LIKE ? OR s.musician LIKE ?) AND (?=0 OR s.idmt=?) AND (?=0 OR s.idu=?) ORDER BY s.datetime DESC,s.ids DESC';
$s=$d->prepare($sql);$flag=$mine?1:0;$s->bind_param('iissiiii',$u['id'],$u['id'],$like,$like,$genre,$genre,$flag,$u['id']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$genres=$d->query('SELECT * FROM z6_musictype ORDER BY idmt')->fetch_all(MYSQLI_ASSOC);$own=music_own_playlists($d,(int)$u['id']);$d->close();
head('mySpotify');music_toolbar('music.php');
?>
<form method="get" action="music.php" class="music-filter card card-body mb-4"><div class="row g-3 align-items-end"><div class="col-12 col-md-5"><label class="form-label" for="search-song">Tytuł lub wykonawca</label><input class="form-control" id="search-song" name="q" value="<?=h($q)?>" maxlength="100"></div><div class="col-12 col-md-3"><label class="form-label" for="filter-genre">Gatunek</label><select class="form-select" id="filter-genre" name="genre"><option value="0">Wszystkie gatunki</option><?php foreach($genres as $g): ?><option value="<?=$g['idmt']?>"<?=$genre===(int)$g['idmt']?' selected':''?>><?=h($g['name'])?></option><?php endforeach; ?></select></div><div class="col-12 col-md-2"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="my-songs" name="mine" value="1"<?=$mine?' checked':''?>><label class="form-check-label" for="my-songs">Tylko moje</label></div></div><div class="col-12 col-md-2"><button class="btn btn-primary w-100" type="submit">Szukaj</button></div></div></form>
<div class="d-flex justify-content-between align-items-center mb-3"><span class="text-body-secondary"><?=count($rows)?> utworów</span><div class="btn-group" aria-label="Widok utworów"><button type="button" class="btn btn-outline-primary" data-music-view="grid">Kafelki</button><button type="button" class="btn btn-outline-primary" data-music-view="list">Lista</button></div></div>
<div id="music-catalog" class="row g-3"><?php foreach($rows as $song): ?><div class="col-12 col-md-6 col-xl-4"><article class="card h-100 music-song"><div class="card-body p-4"><?=music_cover_html((int)$song['ids'],null,$song['coverfilename'],'Okładka '.$song['title'])?><div class="d-flex justify-content-between gap-2 align-items-start"><div><h2 class="h5"><a href="song.php?id=<?=$song['ids']?>"><?=h($song['title'])?></a></h2><p class="mb-2"><?=h($song['musician'])?></p></div><span class="badge text-bg-secondary"><?=h($song['genre'])?></span></div><p class="small text-body-secondary">Dodano: <?=h(cloud_time($song['datetime']))?> · <?=h($song['username'])?></p><?=music_play_button($song)?><?php music_add_form($song,$own); ?></div></article></div><?php endforeach; ?></div>
<?php if(!$rows): ?><div class="card card-body text-center py-5"><h2 class="h4">Brak utworów</h2><p class="text-body-secondary">Dodaj nagranie lub wybierz publiczną playlistę.</p><div><a class="btn btn-primary" href="select.php">Dodaj utwór</a></div></div><?php endif; ?>
<?php foot(); ?>
